  background:transparent; flex:1 1 0; min-width:6em; overflow:hidden;
  text-align:center; display:flex; align-items:center; justify-content:center;
}
.mw-section-label span {
  color:rgba(0,0,0,0.5); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;
}
.mw-section-label.selected { background:rgba(120,120,120,1); border:1px solid transparent; }
.mw-section-label.selected span { color:rgba(255,255,255,1); font-weight:bold; }
.mw-section-label.playing { background:transparent; border:1px solid rgba(0,0,0,0.3); }
.mw-section-label.playing span { color:rgba(0,0,0,1); font-weight:bold; }
#mw-3d-toggle { padding:4px 8px; display:flex; align-items:center; gap:4px; }
#mw-3d-toggle label { cursor:pointer; display:flex; align-items:center; gap:4px; font-size:0.9em; color:rgba(0,0,0,0.7); }

.animator-box {
    font-family: system-ui, sans-serif;
    padding: 16px;
    background: #f5f5f5;
    border-radius: 8px;
    width: 400px;
}

.button-row {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-bottom: 16px;
}

.animator-btn {
    padding: 6px 12px;
    font-size: 13px;
    font-weight: 600;
    color: white;
    background: #5C8020;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.animator-btn:hover {
    transform: translateY(-1px);
}

.animator-btn.stop {
    background: #E87F24;
}

.restart-btn {
    background: #5C8020;
    min-width: 80px;
}

.restart-btn:hover {
    background: var(--grass-9);
}

.progress-row {
    display: flex;
    align-items: center;
    gap: 12px;
}

.animator-text {
    font-size: 13px;
    color: #555;
    white-space: nowrap;
    min-width: 50px;
    text-align: right;
}

.animator-track {
    flex: 1;
    height: 6px;
    background: #ddd;
    border-radius: 3px;
    overflow: hidden;
}

.animator-fill {
    height: 100%;
    width: 0%;
    background: #5C8020;
    border-radius: 3px;
    transition: width 0.2s ease;
}
